def para(s,prefix,new):
 parts=s.split('\n\n');hits=[i for i,p in enumerate(parts) if p.startswith(prefix)];assert len(hits)==1,(prefix,hits);parts[hits[0]]=new;return '\n\n'.join(parts)
def table(s,prefix,new):
 lines=s.splitlines();hits=[i for i,l in enumerate(lines) if l.startswith(prefix)];assert len(hits)==1,(prefix,hits);lines[hits[0]]=new;return '\n'.join(lines)+'\n'
def save(path,s):path.write_text(s)

